+    return header.workspaceIdentifier.id || header.workspaceIdentifier.workspaceId || null;
+  }
+  return header.workspaceId || header.workspaceID || null;
+}
+
+function setWorkspaceIdOnHeader(header, newId) {
+  if (!header || typeof header !== "object") return false;
+  if (header.workspaceIdentifier && typeof header.workspaceIdentifier === "object") {
+    if ("id" in header.workspaceIdentifier) {
+      header.workspaceIdentifier.id = newId;
+      return true;
+    }
+    if ("workspaceId" in header.workspaceIdentifier) {
+      header.workspaceIdentifier.workspaceId = newId;
+      return true;
+    }
+  }
+  if ("workspaceId" in header) {
+    header.workspaceId = newId;
+    return true;
+  }
